    def longestCommonPrefix(self, s, t):
        i = 0
        while i < len(s) and i < len(t) and s[i] == t[i]:
            i += 1
        if i == len(s) or i == len(t):
            return i
        j = i
        while j + 1 < len(s) and j < len(t) and s[j + 1] == t[j]:
            j += 1
        return j

