class Solution {
public:
    int longestCommonPrefix(string s, string t) {
        auto lcp = [](const string& a, const string& b) {
            int i = 0;
            while (i < (int)a.size() && i < (int)b.size() && a[i] == b[i]) i++;
            return i;
        };
        int best = lcp(s, t);
        for (int k = 0; k < (int)s.size(); k++) {
            string r = s.substr(0, k) + s.substr(k + 1);
            best = max(best, lcp(r, t));
        }
        return best;
    }
};

