class Solution {
    private int lcp(String a, String b) {
        int i = 0;
        while (i < a.length() && i < b.length() && a.charAt(i) == b.charAt(i)) i++;
        return i;
    }
    public int longestCommonPrefix(String s, String t) {
        int best = lcp(s, t);
        for (int k = 0; k < s.length(); k++)
            best = Math.max(best, lcp(s.substring(0, k) + s.substring(k + 1), t));
        return best;
    }
}

